var (
	schemaVersion int
	once          sync.Once
	byID          map[uint16]Product
	order         []Product
)

func load() {
	once.Do(func() {
		// v2: {"schemaVersion":2,"models":{...}}; v1: the bare map.
		var env struct {
			SchemaVersion int                `json:"schemaVersion"`
			Models        map[string]Product `json:"models"`
		}
		m := map[string]Product(nil)
		if err := json.Unmarshal(raw, &env); err == nil && env.Models != nil {
			schemaVersion, m = env.SchemaVersion, env.Models
		} else if err := json.Unmarshal(raw, &m); err != nil {
			panic("models: embedded models.json: " + err.Error())
		} else {
			schemaVersion = 1
		}
		byID = make(map[uint16]Product, len(m))
		for k, p := range m {
			n, err := strconv.ParseUint(k, 10, 16)
			if err != nil {
				continue
			}
			p.VendorID = uint16(n)
			byID[p.VendorID] = p
			order = append(order, p)
		}
		sort.Slice(order, func(i, j int) bool { return order[i].VendorID < order[j].VendorID })
	})
}

// Lookup returns the snapshot entry for a vendorId.
func Lookup(vendorID uint16) (Product, bool) {
	load()
	p, ok := byID[vendorID]
	return p, ok
}

// All returns every product ordered by vendorId.
func All() []Product {
	load()
	return append([]Product(nil), order...)
}

// Count is the number of products in the snapshot.
func Count() int {
	load()
	return len(order)
}

// SchemaVersion is the schema of the embedded snapshot (1 or 2).
func SchemaVersion() int {
	load()
	return schemaVersion
}
